from dataclasses import dataclass

@dataclass
class Point:
    x: float
    y: float

    def norm2(self):
        return self.x * self.x + self.y * self.y

    def move(self, dx, dy):
        self.x += dx
        self.y += dy

@dataclass
class Particle:
    position: Point
    velocity: Point

    def norm2(self):
        return self.position.norm2()

    def step(self):
        self.position.move(self.velocity.x, self.velocity.y)

p = Point(3.0, 4.0)
p.move(1.0, 2.0)
print(p.norm2())
q = Particle(p, Point(0.25, 0.5))
q.step()
print(q.norm2())

